def add_strings(x, y):                       # helper: add two non-negative decimal strings
    i, j = len(x) - 1, len(y) - 1
    carry = 0
    result = []
    while i >= 0 or j >= 0 or carry:
        total = carry
        if i >= 0:
            total += int(x[i])
            i -= 1
        if j >= 0:
            total += int(y[j])
            j -= 1
        result.append(str(total % 10))
        carry = total // 10
    return "".join(reversed(result))

def multiply(num1, num2):
    if num1 == "0" or num2 == "0":
        return "0"                                # multiplying by zero is always zero
    count = int(num2)                             # treat num2 as how many times to add num1
    total = "0"
    for _ in range(count):
        total = add_strings(total, num1)             # add num1 to the running total, one at a time
    return total


if __name__ == "__main__":
    num1, num2 = "123", "456"
    print(multiply(num1, num2))

