import java.util.*;

public class Main {
    String multiply(String num1, String num2) {
        if (num1.equals("0") || num2.equals("0")) {
            return "0";                                          // multiplying by zero is always zero
        }
        int n = num1.length(), m = num2.length();
        int[] result = new int[n + m];                        // one slot for every possible digit position
        for (int i = n - 1; i >= 0; i--) {
            for (int j = m - 1; j >= 0; j--) {
                int mul = (num1.charAt(i) - '0') * (num2.charAt(j) - '0');  // multiply this one pair of digits
                int p1 = i + j, p2 = i + j + 1;                    // the two positions this product can affect
                int total = mul + result[p2];
                result[p2] = total % 10;                            // the digit that lands in this position
                result[p1] += total / 10;                            // whatever carries into the next position
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int d : result) {
            sb.append(d);
        }
        int start = 0;
        while (start < sb.length() - 1 && sb.charAt(start) == '0') {
            start++;                                                    // skip any leading zeroes
        }
        return sb.substring(start);
    }

    public static void main(String[] args) {
        String num1 = "123", num2 = "456";
        Main solution = new Main();
        System.out.println(solution.multiply(num1, num2));
    }
}

